#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import { contractFor, metadataError } from "./agent-stage-result-contract.mjs";

const [resultFile, allowedPrefix, markerFile, stage] = process.argv.slice(2);
const fail = (message, code = 2) => { console.error(message); process.exit(code); };
try { contractFor(stage); }
catch (error) { fail(error.message); }

let result;
try { result = JSON.parse(fs.readFileSync(resultFile, "utf8")); }
catch (error) { fail(`invalid stage result JSON: ${error.message}`); }

const exact = (object, keys) => object && typeof object === "object" && !Array.isArray(object)
  && Object.keys(object).sort().join("|") === [...keys].sort().join("|");
if (!exact(result, ["status", "artifact", "reason", "metadata"])) fail("stage result has invalid top-level fields");
if (!exact(result.metadata, ["verdict", "action", "slug"])) fail("stage result has invalid metadata fields");
if (!["ok", "abort"].includes(result.status)) fail("stage result has invalid status");
if (typeof result.artifact !== "string" || typeof result.reason !== "string") fail("stage result string fields are invalid");
for (const key of ["verdict", "action", "slug"]) {
  if (result.metadata[key] !== null && typeof result.metadata[key] !== "string") fail(`invalid metadata.${key}`);
}

if (result.status === "abort") {
  if (result.artifact !== "" || result.reason === "") fail("aborted stage must have an empty artifact and non-empty reason");
  if (Object.values(result.metadata).some((value) => value !== null)) fail("aborted stage must leave all metadata values null");
  fail(`stage aborted: ${result.reason}`, 4);
}
if (result.reason !== "") fail("successful stage result must have an empty reason");
if (!result.artifact || path.isAbsolute(result.artifact) || result.artifact.includes("\0")
    || result.artifact.split(/[\\/]/).includes("..")) {
  fail("artifact must be a safe repository-relative path");
}
if (!(result.artifact === allowedPrefix || result.artifact.startsWith(`${allowedPrefix}/`))) {
  fail(`artifact is outside allowed path: ${result.artifact}`);
}

const root = process.cwd();
const absolute = path.resolve(root, result.artifact);
const rootPrefix = `${root}${path.sep}`;
if (!absolute.startsWith(rootPrefix) || !fs.existsSync(absolute) || !fs.statSync(absolute).isFile()) {
  fail("artifact does not exist as a regular file");
}
if (fs.statSync(absolute).mtimeMs < fs.statSync(markerFile).mtimeMs) {
  fail("artifact was not created or updated by this stage");
}

const contractError = metadataError(stage, result.metadata, result.artifact);
if (contractError) fail(contractError);

const content = fs.readFileSync(absolute, "utf8");
if (stage === "analyze") {
  if ((content.match(/^verdict: /gm) || []).length !== 1
      || !content.includes(`verdict: ${result.metadata.verdict}`)) {
    fail("analysis artifact and metadata.verdict differ");
  }
  if ((content.match(/^action: /gm) || []).length !== 1
      || !content.includes(`action: ${result.metadata.action}`)) {
    fail("analysis artifact and metadata.action differ");
  }
}
if (stage === "review") {
  if ((content.match(/^verdict: /gm) || []).length !== 1
      || !content.includes(`verdict: ${result.metadata.verdict}`)) {
    fail("review artifact and metadata.verdict differ");
  }
}

process.stdout.write(result.artifact);
#!/usr/bin/env node

import fs from "node:fs";

const slugPattern = "^[a-z0-9-]{12,50}$";
const stages = new Set(["search", "plan", "run", "analyze", "draft", "review", "revise"]);
const analysisVerdicts = ["confirmed", "conditional", "not-reproduced", "unsupported", "inconclusive"];
const analysisActions = ["draft", "rerun", "stop"];
const reviewVerdicts = ["pass", "fix", "rerun", "blocker"];

export function contractFor(stage) {
  if (!stages.has(stage)) throw new Error(`unknown agent stage: ${stage}`);
  return {
    verdict: stage === "analyze" ? analysisVerdicts : (stage === "review" ? reviewVerdicts : null),
    action: stage === "analyze" ? analysisActions : null,
    slug: ["draft", "review", "revise"].includes(stage),
  };
}

export function schemaFor(stage) {
  const contract = contractFor(stage);
  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    type: "object",
    properties: {
      status: { type: "string", enum: ["ok", "abort"] },
      artifact: { type: "string" },
      reason: { type: "string" },
      metadata: {
        type: "object",
        properties: {
          verdict: contract.verdict
            ? { type: ["string", "null"], enum: [...contract.verdict, null] }
            : { type: "null" },
          action: contract.action
            ? { type: ["string", "null"], enum: [...contract.action, null] }
            : { type: "null" },
          slug: contract.slug
            ? { type: ["string", "null"], pattern: slugPattern }
            : { type: "null" },
        },
        required: ["verdict", "action", "slug"],
        additionalProperties: false,
      },
    },
    required: ["status", "artifact", "reason", "metadata"],
    additionalProperties: false,
  };
}

export function promptFor(stage) {
  const contract = contractFor(stage);
  const parts = [
    contract.verdict
      ? `metadata.verdict must be one of ${contract.verdict.map((value) => `"${value}"`).join(", ")}`
      : "metadata.verdict must be null",
    contract.action
      ? `metadata.action must be one of ${contract.action.map((value) => `"${value}"`).join(", ")}`
      : "metadata.action must be null",
    contract.slug ? "metadata.slug must be the article slug" : "metadata.slug must be null",
  ];
  return `For a successful ${stage} result, ${parts.join("; ")}. For an aborted result, all metadata values must be null.`;
}

export function metadataError(stage, metadata, artifact) {
  const contract = contractFor(stage);
  if (contract.verdict ? !contract.verdict.includes(metadata.verdict) : metadata.verdict !== null) {
    return `${stage} has an invalid metadata.verdict`;
  }
  if (contract.action ? !contract.action.includes(metadata.action) : metadata.action !== null) {
    return `${stage} has an invalid metadata.action`;
  }
  if (contract.slug) {
    if (!new RegExp(slugPattern).test(metadata.slug || "")) return `${stage} requires a valid slug`;
  } else if (metadata.slug !== null) {
    return `${stage} must leave metadata.slug null`;
  }
  if (["draft", "revise"].includes(stage) && artifact.split("/").at(-1) !== `${metadata.slug}.md`) {
    return "article filename and metadata.slug differ";
  }
  return null;
}

function usage() {
  throw new Error("usage: agent-stage-result-contract.mjs schema STAGE OUTPUT | prompt STAGE");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  try {
    const [command, stage, target] = process.argv.slice(2);
    if (command === "schema" && target) {
      fs.writeFileSync(target, `${JSON.stringify(schemaFor(stage), null, 2)}\n`);
    } else if (command === "prompt" && stage && !target) {
      process.stdout.write(promptFor(stage));
    } else {
      usage();
    }
  } catch (error) {
    console.error(error.message);
    process.exit(2);
  }
}
